    x.strokeStyle = C.white; x.lineWidth = 1.4; for (const d of [-1, 1]) { x.beginPath(); x.moveTo(cx + d * 11, base - 24); x.quadraticCurveTo(cx + d * 17, base - 24, cx + d * 11, base - 16); x.stroke(); }
