      for (let k = 0; k < 5; k++) { const t = 0.22 + k * 0.17, ex = -6 - 28 * t, ey = 2 + 11 * t * t + 2; x.fillStyle = C.gold; x.beginPath(); x.arc(ex, ey, 2.4, 0, Math.PI * 2); x.fill(); x.fillStyle = C.blue; x.beginPath(); x.arc(ex, ey, 1.4, 0, Math.PI * 2); x.fill(); }
