    ctx.strokeStyle = '#f4f0e6'; ctx.lineWidth = 1 * u; ctx.beginPath(); ctx.moveTo(x0 - w / 2 - 1 * u, y0 - h + 0.3 * u); ctx.lineTo(x0, y0 - h - rh); ctx.lineTo(x0 + w / 2 + 1 * u, y0 - h + 0.3 * u); ctx.stroke();
