    ctx.fillStyle = '#f4f0e6'; ctx.fillRect(x0 - w * 0.25, y0 - h * 0.8, w * 0.5, h * 0.8); ctx.fillStyle = '#3e2622'; ctx.fillRect(x0 - w * 0.25 + 0.9 * u, y0 - h * 0.8 + 0.9 * u, w * 0.5 - 1.8 * u, h * 0.8 - 0.9 * u);
