  ctx.strokeStyle = '#e0c088'; ctx.lineWidth = 0.9 * u; ctx.beginPath(); ctx.moveTo(bx - 1 * u, by - 3.6 * u); ctx.lineTo(bx + 2.6 * u, by + 5.6 * u); ctx.moveTo(bx + 2.6 * u, by - 3.6 * u); ctx.lineTo(bx - 1 * u, by + 5.6 * u); ctx.stroke();
