    R(fx, fy, fw, fh, C.cream);
    for (let j = fy + 3; j < fy + fh - 1; j += 6) for (let i = fx + 3 + ((j - fy - 3) % 12 ? 3 : 0); i < fx + fw - 1; i += 6) R(i, j, 1, 1, C.cream2);
