        if (t > 0.3 && t < 0.35) k = nx < -0.4 ? 3 : nx < 0.3 ? 2 : 1;
        if (t > 0.35 && t < 0.38) k = 0;
        if (t > 0.45 && t < 0.66) { const q = ((px - px0 + 40) % 5), r = py - Math.round(top + h * 0.555); if ((q === 0 && Math.abs(r) <= 2) || (Math.abs(r) === 3 && q !== 0)) k = 0; }
