  for (const [a, b, r] of [[128, 42, 3], [138, 41, 3.6], [150, 42, 3.2], [156, 46, 2.6]]) { disc(a, b, r, '#35633a'); disc(a - r * 0.3, b - r * 0.3, r * 0.5, '#4f8a48'); }
  poly([[0, 70], [8, 72], [14, 78], [12, 90], [6, 100], [0, 100]], '#5a8c46');
