  ctx.fillStyle = '#a8916c'; roundRect(ctx, X(5), X(6.5), X(106), X(87.5), X(8.5)); ctx.fill(); roundRect(ctx, X(108), X(43), X(17), X(15.5), X(5.5)); ctx.fill();
  ctx.strokeStyle = '#947c5a'; ctx.lineWidth = X(0.8);
