  for (let k = 0; k < 3; k++) front.push([cx - 13 + k * 13 + (R() - 0.5) * 1.5, 59.5 + (R() - 0.5) * 1.5, 15 + R() * 1.5, 6.8, (k - 1) * 0.2 + (R() - 0.5) * 0.3]);
  for (const c of back) cevap(...c);
