  ctx.save(); ctx.beginPath(); ctx.ellipse(X(cx), X(61.5), X(40), X(16.5), 0, 0, Math.PI * 2); ctx.ellipse(X(cx), X(56.5), X(37.5), X(12), 0, 0, Math.PI * 2); ctx.clip('evenodd');
  ctx.fillStyle = '#c27a3a'; ctx.fillRect(0, X(58), W, H);
