    ctx.fillStyle = '#dcd6c8'; ctx.beginPath(); ctx.ellipse(X(a + 0.6 * f), X(b + 1), X(3.2 * s), X(1.4 * s), 0, 0, Math.PI * 2); ctx.fill();
