    ctx.fillStyle = '#2e2620'; ctx.beginPath(); ctx.ellipse(X(a + 4.2 * s * f), X(b - 0.4 * s), X(1.4 * s), X(1.1 * s), f * 0.4, 0, Math.PI * 2); ctx.fill();
