    ctx.fillStyle = stoneL; ctx.fillRect(x0 - 0.6 * u, y0 - 0.4 * u, w * u + 1.2 * u, 1.4 * u);
    ctx.fillStyle = hole; ctx.fillRect(a * W - 2 * u, y0 + h * u * 0.3, 2 * u, 5.4 * u);
