  ctx.fillStyle = cyl; ctx.fillRect(rt - rw / 2, wl - rh, rw, rh); ctx.beginPath(); ctx.ellipse(rt, wl, rw / 2, 1.6 * u, 0, 0, Math.PI); ctx.fill();
