  ctx.fillStyle = stoneD; ctx.fillRect(rt - rw / 2, wl - rh + 2 * u, rw, 1.2 * u);
  ctx.fillStyle = hole; ctx.fillRect(rt - 2.4 * u, wl - rh + 7 * u, 2 * u, 5 * u); ctx.fillRect(rt - 2.4 * u, wl - 11 * u, 2 * u, 5 * u);
