  ctx.fillStyle = '#4a3a3e'; ctx.beginPath(); ctx.moveTo(gx - 18 * u, gy - 2.6 * u); ctx.lineTo(gx + 10 * u, gy - 2.6 * u); ctx.lineTo(gx + 10 * u, gy + 1.6 * u); ctx.lineTo(gx - 16 * u, gy + 1.6 * u); ctx.fill();
