  ctx.fillStyle = '#2a2a3a'; ctx.fillRect(gx + 10 * u, gy - 3 * u, 10 * u, 4.6 * u);
  ctx.fillStyle = '#f2ece2'; ctx.fillRect(gx + 12 * u, gy - 8.4 * u, 6 * u, 5.4 * u); ctx.fillStyle = '#2e3a5a'; ctx.fillRect(gx + 13.2 * u, gy - 7.2 * u, 3.6 * u, 1.8 * u);
