  for (let k = 0; k < 10; k++) tree(0.01 + k * 0.029, 0.27 + k * 0.032, 11 + (k % 3) * 2.5, k % 2 ? '#22443a' : '#2a5440');
  for (let k = 0; k < 9; k++) tree(0.99 - k * 0.03, 0.31 + k * 0.03, 11 + (k % 3) * 2.5, k % 2 ? '#22443a' : '#2a5440');
