  poly([[0.38, 0.72], [0.395, 0.65], [0.41, 0.58], [0.42, 0.52], [0.432, 0.475], [0.462, 0.475], [0.452, 0.55], [0.44, 0.63], [0.432, 0.72]], '#aea696');
  poly([[0.422, 0.51], [0.434, 0.48], [0.455, 0.48], [0.448, 0.53], [0.43, 0.56]], '#cac2b2');
