  const sky = ctx.createLinearGradient(0, 0, 0, H * 0.44); sky.addColorStop(0, '#6474b2'); sky.addColorStop(0.45, '#c09cbc'); sky.addColorStop(0.8, '#f2bc8c'); sky.addColorStop(1, '#f8daa0');
