  ctx.fillStyle = '#5a7e3e'; for (const [a, b, r] of [[0.965, 0.745, 2.4], [0.895, 0.785, 2], [0.815, 0.885, 1.8]]) { ctx.beginPath(); ctx.ellipse(W * a - 0.6 * u, H * b - 0.6 * u, r * 1.4 * u, r * u, 0, 0, Math.PI * 2); ctx.fill(); }
