  ctx.strokeStyle = '#5a3424'; ctx.lineCap = 'round'; ctx.lineWidth = 2.6 * u; ctx.beginPath(); ctx.moveTo(W * 1.01, H * 0.3); ctx.quadraticCurveTo(W * 0.96, H * 0.18, W * 0.9, H * 0.12); ctx.stroke();
