    ctx.fillStyle = '#3a3634'; ctx.beginPath(); ctx.moveTo(x0 - 0.6 * v, ty - 9 * v); ctx.quadraticCurveTo(x0 + len / 2, ty - 11.6 * v, x0 + len + 0.6 * v, ty - 9 * v); ctx.fill();
