  ctx.fillStyle = '#e8d8b0'; ctx.fillRect(ex + 3.6 * v, ty - 1.9 * v, 9.4 * v, 0.9 * v);
  ctx.fillStyle = '#f4e4a0'; ctx.beginPath(); ctx.arc(ex + 0.8 * v, ty - 6.4 * v, 1 * v, 0, Math.PI * 2); ctx.fill();
