  for (const [a, b, h] of [[0.03, 0.82, 22], [0.08, 0.86, 26], [0.13, 0.9, 20], [0.9, 0.84, 24], [0.95, 0.8, 20], [0.86, 0.9, 18], [0.99, 0.9, 26]]) spruce(a, b, h, '#1e4230', '#2a5a3c');
