  const poly = (pts, col) => { ctx.fillStyle = col; ctx.beginPath(); pts.forEach(([a, b], i) => (i ? ctx.lineTo(a * W, b * H) : ctx.moveTo(a * W, b * H))); ctx.closePath(); ctx.fill(); };
