      const s = n === 1 ? 0.5 : (i + 0.5) / n, px = W * (tcx - w + 2 * w * s + (R() - 0.5) * 0.01), py = H * (yy + (R() - 0.5) * 0.02), col = bcols[bi++ % bcols.length];
