  const R = rng(1225);
  const fx = 79, glowY = 64;                                   // middle of the fire

  // ---- the wall: green striped paper above a dark wood wainscot, the floorboards below
  rect(0, 0, 160, 100, '#284a3a');
  for (let a = 0; a < 160; a += 9) rect(a, 0, 4.5, 60, '#2f5544');
