  ctx.fillStyle = '#1a1110'; ctx.beginPath(); ctx.moveTo(X(ox0), Y(oy1)); ctx.lineTo(X(ox0), Y(oy0 + 7)); ctx.quadraticCurveTo(X(fx), Y(oy0 - 3), X(ox1), Y(oy0 + 7)); ctx.lineTo(X(ox1), Y(oy1)); ctx.fill();
