      dots: (c) => { for (let y = 8, r = 0; y < 36; y += 5, r++) for (let xx = r % 2 ? 0 : 3.5; xx < 26; xx += 7) { c.fillRect(xx + 1, y, 2, 4); c.fillRect(xx, y + 1, 4, 2); } },
