  for (let k = 0; k < 9; k++) { const a = sx - 11 + k * 2.75; line([[a, 62], [a + (k - 4) * 0.5, 67.6 - (k % 2) * 1.6]], 1.4, STRAW[k % 2]); }
  ctx.fillStyle = '#4a8ca6'; shirt(); ctx.fill();
