    ctx.fillStyle = '#f6e8c4'; for (const [px, py] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) ctx.fillRect(X(px * (w / 2 - 0.8) - 0.55), X(py * (h / 2 - 0.8) - 0.55), X(1.1), X(1.1));
    ctx.restore();
