  poly([[sx - 2, hy + 1], [sx + 2, hy + 1], [sx, hy + 3.8]], '#e0702e');
  const smile = []; for (let k = 0; k <= 12; k++) { const t = k / 12 - 0.5; smile.push([sx + t * 12.4, hy + 6.4 - t * t * 8.8 + 0.4]); }
