    rect(c - w / 2 - 1, top - 2.6, w + 2, 2.6, LIT); rect(c - w / 2 - 1.3, top - 3.2, w + 2.6, 1, HI); rect(c + w * 0.2, top - 2.6, w * 0.5 + 1, 2.6, MID);
