  ctx.fillStyle = 'rgba(70,52,96,.3)'; ctx.beginPath(); ctx.moveTo(X(R + 6.4), X(71)); ctx.lineTo(X(R + 14), X(79)); ctx.lineTo(X(R + 6.4), X(79)); ctx.fill();
