      if (kind === 0) { ell(x, y, 3.8, 2.9, '#1f6a2a'); for (const d of [-2, -0.6, 0.8, 2.2]) ell(x + d, y, 0.55, 2.6, '#4a9a3a'); ell(x - 1.4, y - 1.2, 1.2, 0.7, '#8ac46a'); }
